CREATE TABLE movies (
    id SERIAL PRIMARY KEY,
    imdb_id VARCHAR(20) UNIQUE,
    title VARCHAR(500) NOT NULL,
    year INTEGER,
    rated VARCHAR(20),
    runtime_minutes INTEGER,
    rating DECIMAL(3,1),
    vote_count INTEGER,
    plot TEXT,
    poster_url TEXT,
    release_date DATE,
    language VARCHAR(100),
    country VARCHAR(100),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP
);


CREATE TABLE genres (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE movie_genres (
    movie_id INTEGER REFERENCES movies(id),
    genre_id INTEGER REFERENCES genres(id),
    PRIMARY KEY (movie_id, genre_id)
);


CREATE TABLE people (
    id SERIAL PRIMARY KEY,
    imdb_name_id VARCHAR(20) UNIQUE,
    name VARCHAR(255) NOT NULL,
    birth_year INTEGER,
    death_year INTEGER,
    bio TEXT,
    photo_url TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE roles (
    id SERIAL PRIMARY KEY,
    name VARCHAR(50) UNIQUE NOT NULL,
    description VARCHAR(200)
);


CREATE TABLE movie_people (
    movie_id INTEGER REFERENCES movies(id),
    person_id INTEGER REFERENCES people(id),
    role_id INTEGER REFERENCES roles(id),
    character_name VARCHAR(200),
    ordering INTEGER DEFAULT 0,
    PRIMARY KEY (movie_id, person_id, role_id)
);


CREATE TABLE box_office (
    id SERIAL PRIMARY KEY,
    movie_id INTEGER REFERENCES movies(id),
    release_version VARCHAR(50) DEFAULT 'Theatrical',
    region VARCHAR(50) DEFAULT 'Worldwide',
    us_canada_gross BIGINT,
    opening_weekend BIGINT,
    budget BIGINT,
    worldwide_gross BIGINT,
    currency VARCHAR(10) DEFAULT 'USD',
    updated_at TIMESTAMP,
    UNIQUE (movie_id, release_version, region)
);


CREATE TABLE awards (
    id SERIAL PRIMARY KEY,
    movie_id INTEGER REFERENCES movies(id),
    award_name VARCHAR(255) NOT NULL,
    category VARCHAR(200),
    year INTEGER,
    won BOOLEAN DEFAULT FALSE,
    ceremony_date DATE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE user_ratings (
    id SERIAL PRIMARY KEY,
    movie_id INTEGER REFERENCES movies(id),
    user_id VARCHAR(100) NOT NULL,
    rating DECIMAL(3,1) NOT NULL,
    review TEXT,
    rating_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (movie_id, user_id)
);


